    function run(bytes32 hash, uint amount, uint preLockAmount, uint preAmount) public payable {
        require(true);
        c.lockInGuess{value: preLockAmount}(hash);
        (uint preBlock, bytes32 preGuess) = c.guesses(address(this));
        bool reverted;
        if (amount < 1 ether) {
            bool reverted2;
            try c.lockInGuess{value: amount}(hash) { reverted2 = false; } catch { reverted2 = true; }
            reverted = reverted2;
        } else {
            try c.lockInGuess{value: amount}(hash) { reverted = false; } catch { reverted = true; }
        }
        (uint postBlock, bytes32 postGuess) = c.guesses(address(this));
        bool hasPriorGuess = preBlock != 0;
        bool sentEnough = amount >= 1 ether;
        bool expectRevert = hasPriorGuess || !sentEnough;
        assert(reverted == expectRevert);
        if (!reverted) {
            assert(postBlock == block.number + 1 && postGuess == hash);
        } else {
            assert(postBlock == preBlock && postGuess == preGuess);
        }
    }
    receive() external payable {}
}

