    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        bool firstReverted;
        try c.lockInGuess{value: amount}(bytes32(uint256(1))) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.lockInGuess{value: amount}(bytes32(uint256(2))) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        if (amount == 1 ether) {
            assert(!firstReverted && secondReverted);
        } else {
            assert(firstReverted && secondReverted);
        }
    }

    receive() external payable {}
}

