contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 guess, uint lockAmount, uint settleDelay) public payable {
        require(address(this).balance >= lockAmount, "not enough balance for lockInGuess");
        require(settleDelay >= 0, "delay must be non-negative");

        // No state for msg.sender yet, so settle must revert before lockInGuess.
        bool settleBeforeLockReverted;
        try c.settle() {
            settleBeforeLockReverted = false;
        } catch {
            settleBeforeLockReverted = true;
        }

        c.lockInGuess{value: lockAmount}(guess);

        // Advance the chain by the parametrized number of blocks before settling.
        // The test harness must provide enough block depth for this loop.
        if (settleDelay > 0) {
            for (uint i = 0; i < settleDelay; i++) {
                // Force a new block by making a fresh call to c each iteration.
                (bool ok, ) = address(c).call{value: 0}("");
                ok;
            }
        }

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General rule: settle cannot succeed before a guess is locked in,
        // and after lockInGuess it succeeds exactly when at least one block
        // has been mined past the lock block.
        assert(settleBeforeLockReverted && (settleReverted == (settleDelay == 0)));
    }
}

