contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint wrongAmount, bytes32 guess) public payable {
        require(wrongAmount != 1 ether, "wrongAmount must not be 1 ether");
        // Ignore value supplied to run itself; use wrongAmount for the lock attempt.
        // wrongAmount is guaranteed > 0 by uint and != 1 ether.

        bool lockReverted;
        if (address(this).balance >= wrongAmount) {
            try c.lockInGuess{value: wrongAmount}(guess) {
                lockReverted = false;
            } catch {
                lockReverted = true;
            }
        } else {
            // Not enough balance to even attempt; treat as reverted.
            lockReverted = true;
        }

        // If lock did not revert (unexpected, but possible if wrongAmount == 1 ether was invalid),
        // we still proceed to settle. However rule states both lockReverted and settleReverted true
        // when amount != 1 ether. So assert the general implication.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // General rule: whenever lock reverted, settle also reverts.
        assert(!lockReverted || settleReverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 hash, uint amount, bool preLock) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        if (preLock) {
            require(address(this).balance >= 1 ether, "insufficient balance for prelock");
            c.lockInGuess{value: 1 ether}(bytes32(uint256(1)));
        }

        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = preLock || amount != 1 ether;
        assert(reverted == shouldRevert);
    }

    receive() external payable {}
}

