contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 guessSeed) public payable {
        require(address(this).balance >= 1 ether);
        bytes32 guess = keccak256(abi.encodePacked(guessSeed));

        // Set up: make the current sender (this contract) have a pending guess.
        c.lockInGuess{value: 1 ether}(guess);

        // Rule: a caller may only settle once block.number() has advanced beyond the lock-in block.
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || block.number > c.guesses(address(this)).block);
    }

    receive() external payable {}
}

